(()=>{'use strict';let deferred=null;const key='rm-install-dismissed-v1',bar=document.getElementById('install-banner'),button=document.getElementById('install-action'),help=document.getElementById('install-help');const standalone=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;const dismissed=()=>{try{return localStorage.getItem(key)==='1';}catch{return false;}};function hide(){bar.hidden=true;try{localStorage.setItem(key,'1');}catch{}}function show(){if(!standalone()&&!dismissed())bar.hidden=false;}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;button.textContent='Install app';show();});window.addEventListener('appinstalled',()=>{deferred=null;hide();help.hidden=true;});document.getElementById('install-dismiss').addEventListener('click',hide);button.addEventListener('click',async()=>{hide();if(deferred){const event=deferred;deferred=null;try{await event.prompt();await event.userChoice;}catch{help.hidden=false;}}else help.hidden=false;});document.getElementById('install-help-close').addEventListener('click',()=>{help.hidden=true;});document.getElementById('install-menu').addEventListener('click',()=>{if(standalone())return;bar.hidden=false;});if(!standalone())show();if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});})();
